using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Threading;
namespace WorldTime;
// Controlled native-upload samples, own hidden/offscreen parent, no Explorer manipulation.
public static class Ruler028Performance {
 public static void Run(string[] args){
  string report=Path.GetFullPath(args[Array.IndexOf(args,"--report")+1]),temp=Path.Combine(Path.GetTempPath(),"WorldTime-028-perf-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.GetDirectoryName(report)!);bool explorer=args.Contains("--explorer-host");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var samples=new List<object>();var jobs=new List<(int Contacts,RulerMotionMode Mode,bool Pinned,int Seconds)>();foreach(int contacts in new[]{4,100})foreach(var mode in new[]{RulerMotionMode.Static,RulerMotionMode.LowMotion,RulerMotionMode.Dynamic})jobs.Add((contacts,mode,false,10));if(!args.Contains("--desktop-only")){jobs.Add((4,RulerMotionMode.Static,true,10));jobs.Add((4,RulerMotionMode.Dynamic,true,10));}jobs.Add((100,RulerMotionMode.Dynamic,false,60));
  using(var seed=new Store(temp))seed.Save(new State{AppearanceVersion=2,Language="en"});var host=new Host(new Store(temp),true,true);var parent=new Window{Title="动画资源隔离采样",Left=-5000,Top=-5000,Width=1200,Height=500,ShowInTaskbar=false};parent.Show();var w=host.EnsureRuler();bool ring=args.Contains("--ring");if(!explorer)w.Desktop.HostProvider=()=>new WindowInteropHelper(parent).Handle;w.SetMotionPolicyForTest(RulerMotionMode.Dynamic);w.Reveal();if(ring&&!w.SetDisplayMode(WorldTimeView.Ring))throw new Exception(w.ModeError);var process=Process.GetCurrentProcess();var watch=Stopwatch.StartNew();bool warming=false;int index=-1,paint=0,frames=0,rasters=0,renders=0;double cpu=0,start=0;long privateMin=0,privateMax=0;int handleMin=0,handleMax=0;
  void Next(){index++;if(index>=jobs.Count){host.Exiting=true;w.DisposeMotion();w.Desktop.Dispose();host.Tray.Dispose();host.Disk.Dispose();parent.Close();app.Shutdown();return;}var job=jobs[index];host.S.Rows=Enumerable.Range(0,job.Contacts).Select(i=>Ruler028Tests.Contact("perf-"+i,new[]{"UTC","Arabian Standard Time","China Standard Time","UTC+12","UTC-08","SA Western Standard Time"}[i%6],"Contact "+i)).ToList();w.SetPinned(job.Pinned);w.SetMotionMode(job.Mode);w.SetRulerWidth(ring?560:1000);w.Refresh(force:true);if(explorer&&!w.Desktop.Hosted)throw new Exception("Explorer binding failed: "+w.Desktop.BindingError);process.Refresh();cpu=process.TotalProcessorTime.TotalSeconds;start=watch.Elapsed.TotalSeconds;warming=true;paint=w.Desktop.Surface?.PaintCount??0;frames=w.MotionFrames;rasters=w.StaticRasterCount;renders=w.RenderCount;privateMin=privateMax=process.PrivateMemorySize64;handleMin=handleMax=process.HandleCount;}
  var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(_,_)=>{try{if(index<0){Next();return;}process.Refresh();privateMin=Math.Min(privateMin,process.PrivateMemorySize64);privateMax=Math.Max(privateMax,process.PrivateMemorySize64);handleMin=Math.Min(handleMin,process.HandleCount);handleMax=Math.Max(handleMax,process.HandleCount);var job=jobs[index];double duration=watch.Elapsed.TotalSeconds-start;if(warming){if(duration<2)return;warming=false;cpu=process.TotalProcessorTime.TotalSeconds;start=watch.Elapsed.TotalSeconds;paint=w.Desktop.Surface?.PaintCount??0;frames=w.MotionFrames;rasters=w.StaticRasterCount;renders=w.RenderCount;privateMin=privateMax=process.PrivateMemorySize64;handleMin=handleMax=process.HandleCount;return;}if(duration<job.Seconds)return;samples.Add(new{DisplayMode=w.DisplayMode.ToString(),Width=w.Width,job.Contacts,Chosen=job.Mode.ToString(),Effective=w.EffectiveMotionMode.ToString(),job.Pinned,DesktopHosted=w.Desktop.DesktopHosted,NativeHosted=w.Desktop.Hosted,Seconds=duration,CpuSeconds=process.TotalProcessorTime.TotalSeconds-cpu,CpuOneCorePercent=100*(process.TotalProcessorTime.TotalSeconds-cpu)/duration,PrivateMiBMin=privateMin/1048576d,PrivateMiBMax=privateMax/1048576d,HandleMin=handleMin,HandleMax=handleMax,Windows=app.Windows.Count,VisibleClusters=w.Clusters.Count,Paints=(w.Desktop.Surface?.PaintCount??0)-paint,MotionFrames=w.MotionFrames-frames,StaticRasters=w.StaticRasterCount-rasters,SceneRebuilds=w.RenderCount-renders,w.MotionFps,w.MotionRenderMilliseconds,NativeError=w.Desktop.Surface?.PaintError,w.MotionError});File.WriteAllText(report,JsonSerializer.Serialize(new{Source=explorer?"Real Explorer native host; synthetic profile; no physical input acceptance":args.Contains("--desktop-only")?"Offscreen own native desktop-style host; pinned jobs excluded; no physical Explorer acceptance":"Own native host / pinned popup; no physical Explorer acceptance",WarmupSeconds=2,AssemblySHA256=RulerViewAudit.Hash(typeof(RulerWindow).Assembly.Location),Version=typeof(RulerWindow).Assembly.GetName().Version?.ToString(),Samples=samples},new JsonSerializerOptions{WriteIndented=true}));Next();if(index>=jobs.Count)timer.Stop();}catch(Exception e){File.WriteAllText(report+".error",e.ToString());timer.Stop();host.Exiting=true;w.DisposeMotion();w.Desktop.Dispose();host.Tray.Dispose();host.Disk.Dispose();parent.Close();Environment.ExitCode=1;app.Shutdown();}};timer.Start();app.Run();
 }
}
